-- Los seeds de dev insertan productos con id explicito (1..3) en una columna
-- GENERATED BY DEFAULT AS IDENTITY, asi que la secuencia sigue en 1 y el primer
-- alta sin id chocaria con producto_pkey. Se deja por detras del mayor id, igual
-- que hacen los seeds de identity (el setval es del usuario migrador, no del runtime).
SELECT setval(
  pg_get_serial_sequence('producto', 'id'),
  GREATEST(COALESCE((SELECT max(id) FROM producto), 0), 1),
  COALESCE((SELECT max(id) FROM producto), 0) > 0
);
